// Worker entry: serves the Next.js app (OpenNext) and runs Cron Triggers.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

const CRON_ROUTES: Record<string, string> = {
  "*/5 * * * *": "/api/cron/meetings",
  "*/15 * * * *": "/api/cron/emails",
};

export default {
  fetch: handler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const path = CRON_ROUTES[controller.cron];
    if (!path || !env.CRON_SECRET) {
      console.warn(`[cron] skipped "${controller.cron}" (no route or CRON_SECRET)`);
      return;
    }
    // Run the same authenticated API route an external scheduler would call.
    const req = new Request(`https://jarvis.internal${path}`, {
      headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const res: Response = await handler.fetch(req, env, ctx);
    console.log(`[cron] ${path} → ${res.status} ${(await res.text()).slice(0, 300)}`);
  },
} satisfies ExportedHandler<Env>;
